#!/bin/sh\nset -e\n\n# Path to the script under test\nSCRIPT="../src/quote.sh"\n\n# Expected first quote (index 0)\nexpected=\"The early bird gets the worm, but the second mouse gets the cheese.\"\n\n# Run the script with deterministic index 0\noutput=$($SCRIPT 0)\n\nif [ \"$output\" != \"$expected\" ]; then\n  echo \"Test failed: expected '$expected' but got '$output'\"\n  exit 1\nfi\n\necho \"Test passed: deterministic quote output matches expected value.\"\n
